makeMtLab(document.getElementById("lab-l31"),{id:"l31",scenarios:[{"label": "Ví dụ: Gửi lại số đếm", "note": "ON CONFLICT DO NOTHING.", "steps": [{"t": "Lần 1", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">INSERT 0 1<\/span><\/div>"}, {"t": "Lần 2 (gửi lại)", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">INSERT 0 0<\/span><\/div>", "ask": {"q": "Tổng good sau hai lần gửi?", "o": ["5", "10", "0"], "a": 0}}]}, {"label": "Ví dụ: Đổi trạng thái trong giao dịch", "note": "Hai thao tác cùng thành công.", "steps": [{"t": "BEGIN; UPDATE … ; INSERT …", "html": "<p class=\"mt-calc\">Đóng RUNNING, mở DOWN<\/p>"}, {"t": "COMMIT", "html": "<p class=\"mt-calc\">Cả hai có hiệu lực cùng lúc<\/p>"}]}, {"label": "Ví dụ: Mất kết nối giữa giao dịch", "note": "ROLLBACK tự động.", "steps": [{"t": "UPDATE xong, mất mạng trước INSERT", "html": "<p class=\"mt-calc\">Giao dịch không COMMIT<\/p>"}, {"t": "PostgreSQL hủy cả UPDATE", "html": "<p class=\"mt-calc\">Sự kiện RUNNING vẫn mở như trước<\/p>", "say": "<p>Collector gửi lại cả giao dịch.<\/p>"}]}, {"label": "Lỗi: Khóa tự tăng, không khóa tự nhiên", "note": "Gửi lại tạo dòng mới.", "steps": [{"t": "id serial PRIMARY KEY", "html": "<p class=\"mt-calc\">Mỗi INSERT một id mới<\/p>"}, {"t": "Gửi lại", "html": "<p class=\"mt-calc\">Hai dòng good = 5 → tổng 10<\/p>", "ask": {"q": "Sửa thế nào?", "o": ["Thêm khóa (machine_id, ts)", "Xóa cột good"], "a": 0}}]}, {"label": "Bẫy: Thử lại lỗi dữ liệu", "note": "Vi phạm ENUM.", "steps": [{"t": "Thử lại 1 000 lần", "html": "<p class=\"mt-calc\">Vẫn lỗi, log đầy<\/p>"}, {"t": "Sửa", "html": "<p class=\"mt-calc\">Không thử lại lỗi dữ liệu; ghi ERROR, bỏ bản ghi<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l31"),"l31",[{"kind": "num", "t": "Ghi không trùng", "d": "<p>Trả lời bằng một số.<\/p>", "items": [{"q": "Gửi cùng bản ghi (L1-M1, 08:00, good 5) ba lần với ON CONFLICT DO NOTHING. Tổng good?", "a": 5}, {"q": "Không có khóa tự nhiên, gửi ba lần. Tổng good?", "a": 15}, {"q": "Hai bản ghi khác ts, mỗi bản good 5, mỗi bản gửi hai lần (có khóa). Tổng good?", "a": 10}], "hints": ["Có khóa: mỗi ts chỉ một dòng.", "Không khóa: mỗi lần gửi một dòng."], "why": "5; 15; 10."}, {"kind": "pick", "t": "Thử lại không?", "d": "<p>Chọn cách xử lý.<\/p>", "cats": ["Thử lại", "Không thử lại"], "items": [{"q": "Hết thời gian chờ kết nối CSDL", "a": 0}, {"q": "Vi phạm khóa ngoại", "a": 1}, {"q": "Mất mạng giữa giao dịch", "a": 0}, {"q": "Trạng thái không có trong ENUM", "a": 1}], "hints": ["Lỗi tạm thời: thử lại.", "Lỗi dữ liệu: gửi lại vẫn sai."], "why": "Mạng, thời gian chờ: thử lại; lỗi dữ liệu: không."}, {"kind": "order", "t": "Đổi trạng thái an toàn", "d": "<p>Sắp xếp.<\/p>", "items": ["BEGIN", "UPDATE đóng sự kiện đang mở", "INSERT sự kiện mới", "COMMIT"], "hints": ["Mọi thao tác nằm giữa BEGIN và COMMIT.", "Đóng cũ trước, mở mới sau."], "why": "BEGIN → UPDATE → INSERT → COMMIT."}]);
mesSim(document.getElementById("sim-l31"),Object.assign({id:"l31"},{kind:"db",title:"Giao dịch và ghi không trùng",show:"count_delta",
 tables:[{name:"machine",cols:[{n:"machine_id",ty:"text",pk:1}],rows:[{machine_id:"L1-M1"},{machine_id:"L1-M2"},{machine_id:"L1-M3"}]},
 {name:"state_event",cols:[{n:"machine_id",ty:"text",nn:1,fk:"machine:machine_id"},{n:"state",ty:"text",nn:1,check:"state in ('RUNNING','IDLE','DOWN','NO_DATA')"},{n:"start_ts",ty:"timestamptz",nn:1},{n:"end_ts",ty:"timestamptz"}],
  exclude:{key:"machine_id",start:"start_ts",end:"end_ts",name:"state_event_machine_id_period_excl"},
  rows:[{machine_id:"L1-M1",state:"RUNNING",start_ts:"2026-11-12 06:00",end_ts:"2026-11-12 09:00"},{machine_id:"L1-M1",state:"DOWN",start_ts:"2026-11-12 09:00",end_ts:"2026-11-12 09:40"},
   {machine_id:"L1-M1",state:"RUNNING",start_ts:"2026-11-12 09:40",end_ts:"2026-11-12 12:30"},{machine_id:"L1-M1",state:"IDLE",start_ts:"2026-11-12 12:30",end_ts:"2026-11-12 12:50"},{machine_id:"L1-M1",state:"RUNNING",start_ts:"2026-11-12 12:50",end_ts:null}]},{name:"count_delta",cols:[{n:"machine_id",ty:"text",pk:1},{n:"ts",ty:"timestamptz",pk:1},{n:"good",ty:"int"},{n:"reject",ty:"int"}],rows:[]}],
 sql:"BEGIN;\nUPDATE state_event SET end_ts = '2026-11-12 13:00'\n WHERE machine_id = 'L1-M1' AND end_ts IS NULL;  -- đóng sự kiện đang mở\nINSERT INTO state_event VALUES ('L1-M1','DOWN','2026-11-12 13:00', NULL);\nCOMMIT;",
 samples:[{l:"Ghi số đếm",sql:"INSERT INTO count_delta VALUES ('L1-M1','2026-11-12 08:00',5,0);"},{l:"Gửi lại + ON CONFLICT",sql:"INSERT INTO count_delta VALUES ('L1-M1','2026-11-12 08:00',5,0)\nON CONFLICT (machine_id, ts) DO NOTHING;"},
  {l:"Giao dịch hỏng",sql:"BEGIN;\nUPDATE state_event SET end_ts = '2026-11-12 13:30' WHERE machine_id = 'L1-M1' AND end_ts IS NULL;\nINSERT INTO state_event VALUES ('L1-M1','STOP','2026-11-12 13:30', NULL);\nSELECT count(*) FROM state_event;"},{l:"ROLLBACK",sql:"ROLLBACK;"}],
 tasks:[{t:"Chạy giao dịch có sẵn: đóng sự kiện RUNNING đang mở và mở sự kiện DOWN.",check:s=>s.rows("state_event").some(r=>r.state==="DOWN"&&r.end_ts==null)},
  {t:"Chạy “Giao dịch hỏng”: câu INSERT sai làm gì với cả giao dịch? Rồi ROLLBACK.",ok:"Sau một lỗi, mọi lệnh bị bỏ qua tới ROLLBACK; UPDATE trước đó cũng bị hủy: không bao giờ làm được một nửa.",check:(s,c)=>c.has("sql",e=>/aborted/.test(e.err||""))&&c.has("sql",e=>e.cmd==="ROLLBACK")},
  {t:"Ghi số đếm, rồi gửi lại đúng bản ghi đó không có ON CONFLICT.",ok:"duplicate key: khóa chính (machine_id, ts) phát hiện bản gửi lại.",check:(s,c)=>c.has("sql",e=>/duplicate key/.test(e.err||""))},
  {t:"Gửi lại với ON CONFLICT DO NOTHING.",ok:"INSERT 0 0: gửi lại bao nhiêu lần cũng không đếm trùng, nên collector thử lại an toàn.",check:(s,c)=>c.has("sql",e=>e.ok&&e.cmd==="INSERT 0 0")}]}));

